def insertion_sort(a):
    for i in range(1, len(a)):
        key = a[i]                          # card in right hand
        j = i - 1
        while j >= 0 and a[j] > key:
            a[j+1] = a[j]                   # shift bigger cards right
            j -= 1
        a[j+1] = key                        # drop into gap
